test('source investigation cannot run indefinitely or discard a causal concern while refreshing its evidence', withKey(async () => {
  const f = fixture(); let calls = 0;
  const github = {rest: {repos: {getContent: async () => ({data: {encoding: 'base64', content: Buffer.from('new source').toString('base64')}})}}};
  const converged = await investigateChange({...f, github, wait: async () => {}, config: {examiner: 'deepseek-flash', challenger: 'deepseek-flash'}, fetchImpl: async () => {
    calls++; return calls % 2 ? response({request_sources: [`src/new-${calls}.rs`]}) : response({...f.report, snapshot: f.snapshot.digest});
  }});
  assert.equal(calls, 6, 'the final cycle cannot request source; its invalid request is a malformed output, retried');
  assert.equal(converged.inspections.length, 2);
  f.report.snapshot = f.snapshot.digest;
  const draft = structuredClone(f.report); draft.findings.push(finding());
  // The rejection names the concern, so a fresh session can retain or resolve it without guessing.
  const id = JSON.stringify(draft.findings[0].id);
  assert.throws(() => validateInspection(f.report, f.snapshot, [draft]), error => error.message.startsWith('A prior investigation concern') &&
    error.message.includes(`finding ${id} from the earlier draft is neither retained under that identifier nor resolved`));
  assert.ok(validateInspection(f.report, f.snapshot));
  const retained = structuredClone(draft);
  assert.ok(validateInspection(retained, f.snapshot, [draft]));
  // A restatement under the same id names the first field that differs and quotes the earlier draft's text for it. (A
  // different path is refused earlier: the path is derived from the finding's anchor.)
  for (const field of ['cause', 'obligation']) {
    const restated = structuredClone(draft); restated.findings[0][field] = `${draft.findings[0][field]} (reworded)`;
    assert.throws(() => validateInspection(restated, f.snapshot, [draft]), error =>
      error.message.includes(`finding ${id} is restated with a different ${field} than the earlier draft`) &&
      error.message.includes(JSON.stringify(draft.findings[0][field])), field);
  }
  // The quoted earlier text is bounded: a long field is cut at 400 characters.
  const long = structuredClone(draft); long.findings[0].obligation = `${'x'.repeat(500)}`;
  const longer = structuredClone(long); longer.findings[0].obligation = `${'y'.repeat(500)}`;
  assert.throws(() => validateInspection(longer, f.snapshot, [long]), error =>
    error.message.includes(JSON.stringify('x'.repeat(400))) && !error.message.includes('x'.repeat(401)));
  retained.findings[0].cause = 'A different root cannot silently reuse the identifier.';
  assert.throws(() => validateInspection(retained, f.snapshot, [draft]), /prior investigation concern/);
  const closed = structuredClone(f.report);
  closed.resolutions = [{id: draft.findings[0].id, state: 'dismissed', reason: 'The current source proves rejection before durable acceptance.', evidence: ['source']}];
  assert.ok(validateInspection(closed, f.snapshot, [draft]));
  const inspected = await inspect({...f, drafts: [draft], role: 'examiner', model: 'deepseek-flash', fetchImpl: async (_, options) => {
    const supplied = JSON.parse(JSON.parse(options.body).messages[1].content);
    assert.equal(supplied.earlier_concerns_by_this_role[0].id, draft.findings[0].id);
    assert.deepEqual(supplied.earlier_concerns_by_this_role[0].sources[0], {source: 'head', start: 1, end: 2});
    assert.equal(supplied.earlier_concerns_by_this_role[0].factors, undefined);
    return response(closed);
  }});
  assert.equal(inspected.report.resolutions[0].id, draft.findings[0].id);
}));

test('a change with no executable code treats an invalid inapplicable test gate as not required', () => {
  const {snapshot} = fixture();
  snapshot.files = [{path: 'README.md', status: 'modified'}];
  const gate = state => ({units: [], accounting: [], evidence: [], findings: [], gates: [{name: 'test_integrity', state, reason: 'Nothing to test.'}, {name: 'scope_authority', state: 'inapplicable', reason: 'x'}]});
  const converted = materialize(gate('inapplicable'), snapshot);
  assert.equal(converted.gates[0].state, 'satisfied');
  assert.match(converted.gates[0].reason, /No executable code changed/);
  assert.equal(converted.gates[1].state, 'inapplicable', 'other required gates are not rewritten');
  assert.equal(materialize(gate('unresolved'), snapshot).gates[0].state, 'unresolved');
  snapshot.files = [{path: 'src/app.ts', status: 'modified'}];
  assert.equal(materialize(gate('inapplicable'), snapshot).gates[0].state, 'inapplicable', 'code changes keep the invalid state visible');
});

test('an earlier concern that the next examination neither retains nor resolves stands as a finding (issue 126)', withKey(async () => {
  const f = fixture(); f.report.snapshot = f.snapshot.digest;
  const draft = structuredClone(f.report); draft.findings.push(finding());
  const silent = structuredClone(f.report);
  const kept = await inspect({...f, drafts: [draft], role: 'examiner', model: 'deepseek-flash', fetchImpl: async () => response(silent)});
  assert.equal(kept.report.findings.length, 1);
  assert.equal(kept.report.findings[0].id, draft.findings[0].id);
  assert.ok(kept.report.evidence.some(entry => entry.id.startsWith('carried-')), 'the original immutable evidence travels with it');
  assert.ok(validateInspection(kept.report, f.snapshot, [draft]));
  // A changed restatement under the same id is replaced by the original concern; a resolved one is left alone.
  const changed = structuredClone(f.report); changed.findings.push({...finding(), cause: 'A different root cannot silently reuse the identifier.'});
  const restated = await inspect({...f, drafts: [draft], role: 'examiner', model: 'deepseek-flash', fetchImpl: async () => response(changed)});
  assert.equal(restated.report.findings.length, 1);
  assert.equal(restated.report.findings[0].cause, draft.findings[0].cause);
  const verbatim = structuredClone(draft);
  const same = await inspect({...f, drafts: [draft], role: 'examiner', model: 'deepseek-flash', fetchImpl: async () => response(verbatim)});
  assert.ok(!same.report.evidence.some(entry => entry.id.startsWith('carried-')), 'a retained concern is not duplicated');
  const closed = structuredClone(f.report);
  closed.resolutions = [{id: draft.findings[0].id, state: 'dismissed', reason: 'The current source proves rejection before durable acceptance.', evidence: ['source']}];
  const resolved = await inspect({...f, drafts: [draft], role: 'examiner', model: 'deepseek-flash', fetchImpl: async () => response(closed)});
  assert.equal(resolved.report.findings.length, 0);
}));

test('a repair outside the initial envelope is clamped to the changed paths instead of aborting the review (issue 144)', () => {
  const {snapshot} = fixture();
  const facts = (repairPaths) => {
    const sample = template(snapshot);
    const concern = finding();
    concern.anchor = {source: 'head', start: 1, end: 1}; delete concern.path;
    concern.factors = Object.fromEntries(Object.entries(concern.factors).map(([key, value]) => [key, {reason: value.reason, evidence: value.evidence}]));
    concern.repair_paths = repairPaths;
    sample.findings.push(concern);
    return sample;
  };
  assert.deepEqual(materialize(facts(['src/upload.rs', 'src/new-story.stories.tsx', 'src/upload.rs']), snapshot).findings[0].repair_paths, ['src/upload.rs']);
  assert.deepEqual(materialize(facts(['tests/new-test.ts']), snapshot).findings[0].repair_paths, ['src/upload.rs'], 'only outside paths: the finding\'s own file');
  assert.deepEqual(materialize(facts([]), snapshot).findings[0].repair_paths, ['src/upload.rs']);
  assert.deepEqual(materialize(facts(undefined), snapshot).findings[0].repair_paths, undefined, 'a missing list is left to validation');
});

'use strict';

const path = require('node:path');
const {createHash} = require('node:crypto');

const FACTORS = Object.freeze({
  defect: ['necessity', 'confidence', 'severity', 'activation', 'irreversibility', 'reach', 'detection', 'propagation', 'recurrence'],
});
const GATES = Object.freeze(['scope_authority', 'test_integrity', 'security_isolation', 'compatibility_recovery', 'review_completeness']);
const STATES = Object.freeze(['satisfied', 'violated', 'unresolved', 'inapplicable']);
const RULES = Object.freeze({version: 4, defect_threshold: 70, xg_bonus: 20});
const MAX_CITATION_LINES = 40;

function requireThat(condition, message) {
  if (!condition) throw new Error(`Invalid acceptance evidence: ${message}`);
}

// A file of the pull request, safe to show in a rejection: printable ASCII only, bounded.
function named(path) {
  return String(path).replace(/[^\x20-\x7e]/g, '?').slice(0, 120);
}

function text(value) {
  return typeof value === 'string' && value.trim().length > 0 && value.length <= 2000;
}

function keys(value, names) {
  requireThat(value && typeof value === 'object' && !Array.isArray(value) &&
    Object.keys(value).sort().join('\0') === [...names].sort().join('\0'), `expected fields ${names.join(', ')}`);
}

function unique(values, label) {
  requireThat(Array.isArray(values) && values.every(text) && new Set(values).size === values.length, label);
}

function point(value) {
  keys(value, ['value', 'evidence', 'reason']);
  requireThat(Number.isFinite(value.value) && 0 <= value.value && value.value <= 1, 'factor value');
  requireThat(text(value.reason), 'factor explanation');
  unique(value.evidence, 'factor citations');
  requireThat(value.evidence.length > 0, 'factor without evidence');
}

function digest(value) {
  return createHash('sha256').update(JSON.stringify(value)).digest('hex');
}

function impactOf(finding) {
  const v = name => finding.factors[name].value;
  return 1 + 0.25 * v('irreversibility') + 0.20 * v('reach') + 0.20 * v('detection') + 0.20 * v('propagation') + 0.15 * v('recurrence');
}

function findingScore(finding) {
  const v = name => finding.factors[name].value;
  return 100 * v('confidence') * Math.min(1, Math.max(v('necessity'), v('activation') * v('severity') * impactOf(finding)));
}

function scoreReport(report) {
  const findings = report.findings.map(finding => {
    const score = findingScore(finding);
    const xg = Object.values(finding.opportunity).every(value => value === true) ? 1 : 0;
    const priority = Math.min(100, score + RULES.xg_bonus * xg / finding.blast_radius ** 2);
    return {id: finding.id, score, xg, priority, disposition: score >= RULES.defect_threshold ? 'blocking' : 'nonblocking'};
  });
  const integrity = report.gates.find(gate => gate.name === 'test_integrity');
  const blocked = report.gates.some(gate => gate.state === 'violated') || findings.some(finding => finding.disposition === 'blocking');
  const decision = integrity.state === 'violated' ? 'blocked_integrity' : blocked ? 'repair_required' : 'auto_approve';
  return {rules: RULES, findings, decision};
}

// Only languages whose tests name the module under test by an import; same-package
// and inline-test languages (Go, Java, C) cannot be linked this way and are not judged here.
const CODE = /\.(?:[cm]?[jt]sx?|py|rs|rb|php|vue|svelte)$/;
const TEST_PATH = /(?:^|\/)(?:__tests__|tests?|specs?|e2e|stories)\/|\.(?:test|spec|stories)\.[a-z0-9]+$|(?:^|\/)test_[^/]+\.py$|_test\.(?:go|py)$/i;
const isTestPath = name => TEST_PATH.test(name);
const FIXTURE_PATH = /(?:^|\/)(?:__fixtures__|fixtures?|__mocks__|mocks?|testdata|__snapshots__)\//i;
// Everything except documentation, data, configuration, lockfiles, workflows and fixtures can change
// behaviour, in any language; tests are included because weakening one is a behaviour change to the suite.
const INERT = /(?:^|\/)(?:LICENSE|NOTICE|CODEOWNERS|CHANGELOG|README)(?:\.(?:md|txt|rst))?$|(?:^|\/)\.[^/]*ignore$|\.(?:md|mdx|txt|rst|json|jsonc|ya?ml|toml|ini|lock|csv|tsv|svg|png|jpe?g|gif|ico|webp|pdf|snap)$|(?:^|\/)(?:package-lock\.json|yarn\.lock|pnpm-lock\.yaml)$/i;
const isExecutablePath = name => !INERT.test(name) && !FIXTURE_PATH.test(name) && !/\.d\.ts$|\.config\.[a-z]+$/.test(name);
const isCodePath = name => CODE.test(name) && isExecutablePath(name) && !isTestPath(name);

// A module is linked to a test only by an import-like line naming it. A word in
// a test title or an unrelated assertion in the same change is not linkage.
function moduleStem(name) {
  const parts = name.split('/'); const base = parts.pop().replace(/\.[^.]+$/, '');
  // A directory's entry file is named by the directory: index.* (JS), __init__.py (Python), mod.rs (Rust).
  return (base === 'index' || (base === '__init__' && name.endsWith('.py')) || (base === 'mod' && name.endsWith('.rs'))) && parts.length ? parts.pop() : base;
}

// A statement that imports, not a title or comment that merely contains the word.
const IMPORT = /^\s*(?:(?:export\b.*\s)?from\b|import\b|use\b|pub\s+use\b|mod\b|require(?:_relative)?\b|include\b|load\b)|\b(?:require|import)\(/;

const JS_PATH = /\.[cm]?[jt]sx?$/;
const PY_PATH = /\.py$/;
const LINKABLE_PATH = /\.(?:[cm]?[jt]sx?|py)$/;
const EXTENSION = /\.[cm]?[jt]sx?$/;

// Module specifiers of a JavaScript/TypeScript source, from whole statements once comments are
// removed: `import ... from`, `export ... from`, side-effect `import`, and declarations initialised by
// require()/import(). A quoted path in a test title or a comment is not an import.
function specifiersOf(content) {
  const text = content.replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/.*$/gm, '');
  const pattern = /^\s*(?:(?:import|export)\b[^;'"`]*?\bfrom\s*|import\s*|(?:(?:const|let|var)\b[^;=]*=\s*)?(?:await\s+)?(?:require|import)\s*\(\s*)(['"`])([^'"`\n]+)\1/gm;
  const found = [...text.matchAll(pattern)].map(match => match[2]);
  // A declaration may initialise several bindings: `const a = require('./a'), b = require('./b');`.
  for (const declaration of text.matchAll(/^\s*(?:const|let|var)\b[^;]*;/gm)) {
    for (const call of declaration[0].matchAll(/\b(?:require|import)\s*\(\s*(['"`])([^'"`\n]+)\1/g)) found.push(call[2]);
  }
  return [...new Set(found)];
}

// Known files a specifier can name: relative paths, `.js`-for-`.ts` suffixes, `/index`, and the
// `@/`, `~/` and `src/` aliases (matched by path tail, since the alias map is not supplied).
function resolveSpecifier(from, specifier, known) {
  const bare = value => value.replace(EXTENSION, '');
  const alias = /^(?:@|~)\//.test(specifier) || specifier.startsWith('src/');
  if (!specifier.startsWith('.') && !alias) return [];
  const target = (specifier.startsWith('.') ? bare(path.posix.normalize(path.posix.join(path.posix.dirname(from), specifier))) : bare(specifier.replace(/^(?:@|~)\//, ''))).replace(/\/index$/, '');
  return known.filter(candidate => {
    const stem = bare(candidate);
    const full = stem.replace(/\/index$/, '');
    return specifier.startsWith('.') ? full === target : full === target || full.endsWith(`/${target}`);
  });
}

// Comments removed, strings kept: a `#` inside a string literal is text, a trailing comment is not code.
const PY_TEXT = /("(?:[^"\\\n]|\\.)*"|'(?:[^'\\\n]|\\.)*')|#.*$/gm;
const pyStrings = content => content.replace(PY_TEXT, (match, string) => string ?? '');

// A Python file loaded by path or run as a script is linked like an import, by the `file:` target the file
// names exactly. The path is read only from the arguments of a call that loads or runs code
// (spec_from_file_location, run_path, subprocess), as a literal or a chain of literals joined by `/` or
// os.path.join; a path in data, a log line or an open() is not a load.
const PY_LOADERS = /\b(?:spec_from_file_location|run_path|(?:subprocess\.)?(?:run|Popen|call|check_call|check_output))\s*\(/g;
const PY_PATH_LITERAL = /((?:(['"])[^'"\n]+\2\s*\/\s*)*)(['"])([^'"\n]+\.py)\3/g;
const PY_JOIN = /\bjoin\s*\(\s*((?:(['"])[^'"\n]*\2\s*,\s*)*)(['"])([^'"\n]+\.py)\3\s*\)/g;
const PY_QUOTED = /(['"])([^'"\n]*)\1/g;
function callArguments(text, from) {
  let depth = 1; let at = from;
  while (at < text.length && depth) {
    if (text[at] === '(') depth++;
    else if (text[at] === ')') depth--;
    at++;
  }
  return text.slice(from, at);
}
function pythonLoads(text) {
  const found = [];
  const quoted = chain => [...chain.matchAll(PY_QUOTED)].map(item => item[2]);
  for (const call of text.matchAll(PY_LOADERS)) {
    const args = callArguments(text, call.index + call[0].length);
    for (const item of args.matchAll(PY_JOIN)) found.push(`file:${[...quoted(item[1]), item[4]].join('/')}`);
    const flat = args.replace(PY_JOIN, '');
    for (const item of flat.matchAll(PY_PATH_LITERAL)) found.push(`file:${[...quoted(item[1]), item[4]].join('/')}`);
    for (const item of flat.matchAll(/(['"])-m\1\s*,\s*(['"])([\w.]+)\2/g)) found.push(item[3]);
  }
  for (const item of text.matchAll(/\b(?:run_module|import_module|__import__)\s*\(\s*(['"])([\w.]+)\1/g)) found.push(item[2]);
  return found;
}

// Python import targets of a source, from whole statements once comments are removed: `import a.b`,
// `from a.b import c, d` (the module and each name, since a name may be a submodule) and relative
// `from . import x`, `from ..pkg import y`. A relative target keeps its leading dots. Modules loaded by
// path or name (see pythonLoads) are targets too.
function pythonImports(content) {
  const text = pyStrings(content);
  const found = [];
  for (const match of text.matchAll(/^[ \t]*import[ \t]+([\w., \t]+)$/gm)) {
    for (const item of match[1].split(',')) found.push(item.trim().split(/\s+/)[0]);
  }
  for (const match of text.matchAll(/^[ \t]*from[ \t]+(\.*)([\w.]*)[ \t]+import[ \t]+(\([^)]*\)|[^\n]*)/gm)) {
    const base = `${match[1]}${match[2]}`;
    found.push(base);
    for (const item of match[3].replace(/[()]/g, '').split(',')) {
      const name = item.trim().split(/\s+/)[0];
      if (/^\w+$/.test(name)) found.push(/\.$/.test(base) ? `${base}${name}` : `${base}.${name}`);
    }
  }
  found.push(...pythonLoads(text));
  return [...new Set(found.filter(Boolean))];
}

// One import extractor per language the linker follows (JavaScript/TypeScript and Python).
const importsOf = (name, content) => PY_PATH.test(name) ? pythonImports(content) : specifiersOf(content);

// Directories from the importing file's own up to the repository root, nearest first.
function ancestors(from) {
  const found = [];
  let dir = path.posix.dirname(from);
  while (dir !== '.') {
    found.push(dir);
    dir = path.posix.dirname(dir);
  }
  return [...found, ''];
}

// Import roots the file list proves: the parent of the outermost directory of each chain of __init__.py packages.
const rootsCache = new WeakMap();
function packageRoots(known) {
  if (!rootsCache.has(known)) {
    const packages = new Set(known.filter(name => /(?:^|\/)__init__\.py$/.test(name)).map(name => name.replace(/\/?__init__\.py$/, '')));
    const roots = new Set();
    const parent = dir => path.posix.dirname(dir).replace(/^\.$/, '');
    for (const dir of packages) {
      let top = dir;
      while (top && packages.has(parent(top))) top = parent(top);
      roots.add(parent(top));
    }
    rootsCache.set(known, [...roots].sort());
  }
  return rootsCache.get(known);
}

// Known Python files a target can name. Every match is exact against the file list, never a path tail.
// `pkg.mod` is pkg/mod.py or pkg/mod/__init__.py. A relative target is resolved from the importing file's
// directory. An absolute one is tried under the importing file's directories (nearest first, each also
// with a `src/` below it) and then under the package roots the file list proves; the first location that
// holds the module is the answer. `file:path` names a script by its path, found under the nearest
// directory of the importing file that holds exactly that path.
function resolvePython(from, specifier, known) {
  const files = known.filter(candidate => PY_PATH.test(candidate));
  const under = (root, relative) => path.posix.join(root, relative).replace(/^\.$/, '');
  if (specifier.startsWith('file:')) {
    const literal = specifier.slice(5);
    for (const dir of ancestors(from)) {
      const target = path.posix.normalize(path.posix.join(dir, literal));
      const hits = files.filter(candidate => candidate === target);
      if (hits.length) return hits;
    }
    return [];
  }
  const dots = /^\.*/.exec(specifier)[0].length;
  const module = specifier.slice(dots).split('.').join('/');
  const modulesOf = candidate => candidate.replace(/(?:^|\/)__init__\.py$/, '').replace(PY_PATH, '');
  if (dots) {
    let base = path.posix.dirname(from);
    for (let up = 1; up < dots; up++) base = path.posix.dirname(base);
    const target = path.posix.join(base, module).replace(/^\.$/, '').replace(/\/$/, '');
    return files.filter(candidate => modulesOf(candidate) === target);
  }
  const roots = ancestors(from).flatMap(dir => [dir, under(dir, 'src')]).concat(packageRoots(known));
  for (const root of roots) {
    const target = under(root, module);
    const hits = files.filter(candidate => modulesOf(candidate) === target);
    if (hits.length) return hits;
  }
  return [];
}

const resolveImport = (from, specifier, known) => PY_PATH.test(from) ? resolvePython(from, specifier, known) : resolveSpecifier(from, specifier, known);

// Principled coverage: a changed JS/TS file is covered when a supplied test imports it directly, or
// imports a supplied file (a changed caller, a barrel) that imports it, transitively. Only supplied
// files can be intermediates; a file with no path from any test is not covered.
function reachedByTests(snapshot) {
  const sources = Object.values(snapshot.sources).filter(source => source.ref === snapshot.head_sha && source.kind === 'source' && LINKABLE_PATH.test(source.path));
  const known = [...new Set([...sources.map(source => source.path), ...snapshot.files.map(file => file.path), ...(snapshot.test_imports || []).map(item => item.path)])];
  const edges = new Map(sources.map(source => [source.path, importsOf(source.path, source.content)]));
  const roots = [...sources.filter(source => isTestPath(source.path)).map(source => source.path), ...(snapshot.test_imports || []).filter(item => isTestPath(item.path)).map(item => item.path)];
  for (const item of snapshot.test_imports || []) edges.set(item.path, item.specifiers);
  const reached = new Map();
  for (const root of new Set(roots)) {
    const seen = new Set(); const queue = [root];
    while (queue.length) {
      const from = queue.shift();
      for (const specifier of edges.get(from) || []) for (const target of resolveImport(from, specifier, known)) {
        if (seen.has(target)) continue;
        seen.add(target); if (!isTestPath(target)) queue.push(target);
        reached.set(target, [...(reached.get(target) || []), root]);
      }
    }
  }
  return reached;
}

// Controller-computed linkage shown to the reviewers: which supplied or discovered tests exercise each
// changed code file, directly or through supplied callers and barrels. A reviewer must not report
// "no test imports this file" for a file listed here.
function coveringTests(snapshot) {
  const reached = reachedByTests(snapshot);
  return Object.fromEntries(snapshot.files.filter(file => file.status !== 'removed' && isCodePath(file.path))
    .map(file => [file.path, (reached.get(file.path) || []).slice(0, 5)]));
}

// A change is non-behavioural only when everything it adds or removes is shown to be inert:
// blank lines, comment-only lines, anchored type-only declarations, and import/re-export statements
// whose normalized VALUE specifiers (module path and imported names) are identical on the removed and
// added sides (re-ordered or re-wrapped). Anything else, including any trailing code on a line, is behavioural.
const IMPORT_STATEMENT = /(?:^|(?<=[\s;]))(?:import(?:\s+type)?\s*(?:[\w$]+\s*,?\s*)?(?:\*\s*as\s+[\w$]+|\{[^{}]*\})?\s*from\s*|import\s*|export(?:\s+type)?\s*(?:\*(?:\s*as\s+[\w$]+)?|\{[^{}]*\})\s*from\s*)(['"])[^'"\n]+\1[ \t]*;?/g;
const TYPE_NAME = String.raw`[\w$]+`;
const INERT_PARTS = [
  String.raw`;?`,
  String.raw`\/\/.*`,
  String.raw`\/\*(?:(?!\*\/).)*\*\/`,
  String.raw`(?:export\s+)?(?:declare\s+)?type\s+${TYPE_NAME}(?:<[^>;{}()]*>)?\s*=\s*[^;(){}\x60]*;?`,
  String.raw`(?:export\s+)?(?:declare\s+)?interface\s+${TYPE_NAME}(?:<[^>;{}()]*>)?(?:\s+extends\s+[\w$.,<> ]+)?\s*\{\s*(?:${TYPE_NAME}\??:\s*[\w$<>\[\]|& '".]+[;,]?\s*)*\}`,
];
const INERT_LINE = new RegExp(`^(?:${INERT_PARTS.join('|')})$`);

function importSpecifiers(statement) {
  const module = /(['"])([^'"\n]+)\1/.exec(statement)[2];
  const clause = statement.slice(0, statement.lastIndexOf(module)).replace(/\s*from\s*['"]?$/, '').replace(/['"]$/, '');
  if (/^(?:import|export)\s+type\b/.test(statement)) return [];
  const body = clause.replace(/^(?:import|export)\s*/, '').trim();
  if (!body || !/from\s*['"]/.test(statement)) return [`${module}|side-effect`];
  const found = [];
  const named = /\{([^{}]*)\}/.exec(body);
  const head = body.replace(/\{[^{}]*\}/, '').replace(/,\s*$/, '').trim();
  if (head) found.push(`${module}|${head.replace(/\s+/g, ' ')}`);
  for (const item of (named ? named[1] : '').split(',').map(value => value.trim().replace(/\s+/g, ' ')).filter(Boolean)) {
    if (!/^type\s/.test(item)) found.push(`${module}|${item}`);
  }
