}

// A file added whole carries its text twice, in the patch and in its head source. The local
// collector stores the patch header only and marks the body as the head source; this restores the
// exact patch, so every consumer sees the same bytes whichever form was stored.
function patchOf(snapshot, file) {
  if (file.patch_body !== 'head_source') return file.patch;
  const lines = snapshot.sources[file.head_source].content.split('\n');
  const final = lines[lines.length - 1] === '';
  if (final) lines.pop();
  return `${file.patch}${lines.map(line => `+${line}`).join('\n')}\n${final ? '' : '\\ No newline at end of file\n'}`;
}

// GitHub lists no patch for a change that shows no text: an empty file added or removed, or a rename that
// changes nothing. Only the immutable contents prove it, so a missing patch for anything else stays unavailable.
function showsNoText(status, base, head) {
  return (status === 'added' && head === '') || (status === 'removed' && base === '') ||
    (status === 'renamed' && typeof base === 'string' && base === head);
}

// A source with no nonblank line holds nothing a reviewer could cite.
const citable = source => Boolean(source?.content.trim());

function nonBehavioural(patch) {
  if (typeof patch !== 'string') return false;
  // Contiguous runs of one sign are one edit. A multi-line block comment is dropped only when the run
  // itself opens it at a line start and closes it at a line end; a ` * ` line without its opener in the
  // run is code-shaped and stays behavioural.
  const runs = {'-': [], '+': []}; let run = null;
  for (const line of patch.split('\n')) {
    const sign = /^(?:\+\+\+|---)/.test(line) ? null : /^[+-]/.test(line) ? line[0] : null;
    if (sign && run?.sign === sign) run.lines.push(line.slice(1));
    else {run = sign ? {sign, lines: [line.slice(1)]} : null; if (run) runs[sign].push(run);}
  }
  const side = sign => {
    const text = runs[sign].map(item => item.lines.join('\n').replace(/^[ \t]*\/\*(?:(?!\*\/)[\s\S])*\*\/[ \t]*$/gm, '')).join('\n');
    const specifiers = [];
    const rest = text.replace(IMPORT_STATEMENT, statement => {specifiers.push(...importSpecifiers(statement.trim())); return '';});
    return {specifiers: specifiers.sort(), inert: rest.split('\n').map(line => line.trim()).every(line => line === '' || INERT_LINE.test(line))};
  };
  const removed = side('-'); const added = side('+');
  return removed.inert && added.inert && JSON.stringify(removed.specifiers) === JSON.stringify(added.specifiers);
}

function linked(snapshot, name, reached) {
  if (LINKABLE_PATH.test(name)) return reached.has(name);
  const stem = moduleStem(name).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const token = new RegExp(`(?:^|[\\s'"\`/.:])${stem}(?=$|[\\s'"\`.;,)/])`);
  return Object.values(snapshot.sources).some(source => source.ref === snapshot.head_sha && source.kind === 'source' && isTestPath(source.path) &&
    !JS_PATH.test(source.path) && source.content.split('\n').some(line => IMPORT.test(line) && token.test(line)));
}

// Rust unit tests live inside the production file, in a `#[cfg(test)] mod name { ... }` holding `#[test]`
// functions, so no separate test file imports the module. Such a file is tested when the change touches a
// line inside one of its in-file test modules (an added, edited or removed test, new or existing file), or
// when a supplied integration test of the same package (`<package>/tests/**.rs`) `use`s the module by its
// path under `<package>/src`. Production lines changed beside an untouched test module are not tested: the
// engine holds the source and patch, not the executed lines, so it cannot show those tests reach them.
// That execution and the covered changed lines are proved by the repository's coverage gate.
const RUST_PATH = /\.rs$/;
const RUST_LEXEME = /\/\/[^\n]*|\/\*[\s\S]*?\*\/|r(#*)"[\s\S]*?"\1|b?"(?:\\[\s\S]|[^"\\])*"|b?'(?:\\'|\\[^'\n]+|[^\\'\n])'/g;
const RUST_TEST_MODULE = /#\[cfg\(test\)\]\s*(?:#\[[^\]]*\]\s*)*(?:pub(?:\([^)]*\))?\s+)?mod\s+\w+\s*\{/g;
const RUST_TEST_ATTRIBUTE = /#\[(?:\w+::)*(?:test|rstest|test_case)\b/;
// Comments and literals blanked in place (newlines kept) so braces and attributes inside them are never read.
const blankRust = source => source.replace(RUST_LEXEME, lexeme => lexeme.replace(/[^\n]/g, ' '));

function rustTestSpans(source) {
  const text = blankRust(source); const line = index => text.slice(0, index).split('\n').length; const spans = [];
  for (const module of text.matchAll(RUST_TEST_MODULE)) {
    let depth = 1; let end = module.index + module[0].length;
    while (end < text.length && depth) depth += {'{': 1, '}': -1}[text[end++]] ?? 0;
    if (!depth && RUST_TEST_ATTRIBUTE.test(text.slice(module.index, end))) spans.push([line(module.index), line(end - 1)]);
  }
  return spans;
}

// New-file line number of every added line; a removed line is the position between the new lines around it
// (half a line before the next surviving line), so a removal just outside a span is never inside it.
function changedLines(patch) {
  const lines = []; let at = 0;
  for (const line of `${patch}`.split('\n')) {
    const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))?/.exec(line);
    if (hunk) at = Number(hunk[1]) + (hunk[2] === '0' ? 1 : 0);
    else if (at && /^[+-]/.test(line)) {lines.push(line[0] === '+' ? at++ : at - 0.5);}
    else if (at && line[0] === ' ') at++;
  }
  return lines;
}

function rustTested(snapshot, file, patch) {
  if (!RUST_PATH.test(file.path)) return false;
  const head = snapshot.sources[file.head_source]?.content;
  if (typeof head === 'string') {
    const spans = rustTestSpans(head);
    if (changedLines(patch).some(at => spans.some(([start, end]) => at >= start && at <= end))) return true;
  }
  const module = /^((?:.*\/)?)src\/(.+)\.rs$/.exec(file.path);
  const segments = module ? module[2].split('/') : [];
  if (segments[segments.length - 1] === 'mod') segments.pop();
  if (!segments.length || (segments.length === 1 && /^(?:lib|main)$/.test(segments[0]))) return false;
  const use = new RegExp(`^[ \\t]*(?:pub(?:\\([^)]*\\))?[ \\t]+)?use[ \\t]+(?!(?:std|core|alloc)::)(?:crate|[A-Za-z_]\\w*)::${segments.map(segment => segment.replace(/\W/g, '\\$&')).join('::')}(?!\\w)`, 'm');
  return Object.values(snapshot.sources).some(source => source.ref === snapshot.head_sha && source.kind === 'source' &&
    source.path.startsWith(`${module[1]}tests/`) && RUST_PATH.test(source.path) && use.test(blankRust(source.content)));
}

// Approval needs affirmative, per-file behavioural evidence. An unresolved
// integrity or completeness gate, or changed production code with no supplied
// test that imports it, is missing verification and holds automatic approval.
// A test for one file never satisfies a different changed file.
function approvalHold(report, snapshot) {
  const gate = name => report.gates.find(item => item.name === name).state;
  // The test gate matters when production code changed, or when a test change removes lines (an
  // added assertion that duplicates coverage is harmless). Documentation, data and fixtures have
  // no behaviour to test. A model's "unresolved" without a missing source behind it is an opinion:
  // completeness holds only when the review records, or the controller omitted, missing evidence.
  const executable = snapshot.files.filter(file => isExecutablePath(file.path));
  const testMatters = executable.some(file => (!isTestPath(file.path) && !nonBehavioural(patchOf(snapshot, file))) || (isTestPath(file.path) && /^-(?!--)/m.test(patchOf(snapshot, file))));
  const missing = (snapshot.omitted_sources || []).length > 0 ||
