  const f = fixture(); let calls = 0;
  const github = {rest: {repos: {getContent: async () => ({data: {encoding: 'base64', content: Buffer.from('new source').toString('base64')}})}}};
  const converged = await investigateChange({...f, github, wait: async () => {}, config: {examiner: 'deepseek-flash', challenger: 'deepseek-flash'}, fetchImpl: async () => {
    calls++; return calls % 2 ? response({request_sources: [`src/new-${calls}.rs`]}) : response({...f.report, snapshot: f.snapshot.digest});
  }});
  assert.equal(calls, 6, 'the final cycle cannot request source; its invalid request is a malformed output, retried');
  assert.equal(converged.inspections.length, 2);
  f.report.snapshot = f.snapshot.digest;
  const draft = structuredClone(f.report); draft.findings.push(finding());
  // The rejection names the concern, so a fresh session can retain or resolve it without guessing.
  const id = JSON.stringify(draft.findings[0].id);
  assert.throws(() => validateInspection(f.report, f.snapshot, [draft]), error => error.message.startsWith('A prior investigation concern') &&
    error.message.includes(`finding ${id} from the earlier draft is neither retained under that identifier nor resolved`));
  assert.ok(validateInspection(f.report, f.snapshot));
  const retained = structuredClone(draft);
  assert.ok(validateInspection(retained, f.snapshot, [draft]));
  // A restatement under the same id names the first field that differs and quotes the earlier draft's text for it. (A
  // different path is refused earlier: the path is derived from the finding's anchor.)
  for (const field of ['cause', 'obligation']) {
    const restated = structuredClone(draft); restated.findings[0][field] = `${draft.findings[0][field]} (reworded)`;
    assert.throws(() => validateInspection(restated, f.snapshot, [draft]), error =>
      error.message.includes(`finding ${id} is restated with a different ${field} than the earlier draft`) &&
      error.message.includes(JSON.stringify(draft.findings[0][field])), field);
  }
  // The quoted earlier text is bounded: a long field is cut at 400 characters.
  const long = structuredClone(draft); long.findings[0].obligation = `${'x'.repeat(500)}`;

  const longer = structuredClone(long); longer.findings[0].obligation = `${'y'.repeat(500)}`;
  assert.throws(() => validateInspection(longer, f.snapshot, [long]), error =>
    error.message.includes(JSON.stringify('x'.repeat(400))) && !error.message.includes('x'.repeat(401)));
  retained.findings[0].cause = 'A different root cannot silently reuse the identifier.';
  assert.throws(() => validateInspection(retained, f.snapshot, [draft]), /prior investigation concern/);
  const closed = structuredClone(f.report);
  closed.resolutions = [{id: draft.findings[0].id, state: 'dismissed', reason: 'The current source proves rejection before durable acceptance.', evidence: ['source']}];
  assert.ok(validateInspection(closed, f.snapshot, [draft]));
  const inspected = await inspect({...f, drafts: [draft], role: 'examiner', model: 'deepseek-flash', fetchImpl: async (_, options) => {
    const supplied = JSON.parse(JSON.parse(options.body).messages[1].content);
    assert.equal(supplied.earlier_concerns_by_this_role[0].id, draft.findings[0].id);
    assert.deepEqual(supplied.earlier_concerns_by_this_role[0].sources[0], {source: 'head', start: 1, end: 2});
    assert.equal(supplied.earlier_concerns_by_this_role[0].factors, undefined);
    return response(closed);
  }});
  assert.equal(inspected.report.resolutions[0].id, draft.findings[0].id);
}));

